// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address owner = c.owner();
        vm.deal(address(c), amount);

        uint256 ownerBalanceBefore = owner.balance;

        bool ok;
        vm.prank(owner);
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        if (ok) {
            assertEq(owner.balance, ownerBalanceBefore + amount, "Owner balance did not increase by withdrawn amount");
        }
    }
}
